import React, { useEffect, useState } from 'react'

import { useDispatch, useSelector } from 'react-redux'

import {
    checkTokenValidation,
    getAllOrders,
    logout
} from '../actions/userActions'

import { useHistory } from 'react-router-dom'

import { Table, Spinner } from 'react-bootstrap'

import { dateCheck } from '../components/GetDate'

import SearchBarForOrdersPage from '../components/SearchBarForOrdersPage'

import Message from '../components/Message'


function OrdersListPage() {

    let history = useHistory()

    const dispatch = useDispatch()

    const placeholderValue =
        "Search orders by Customer Name, Address or by Ordered Item"


    // =========================================
    // CURRENT DATE
    // =========================================

    const todays_date =
        dateCheck(
            new Date().toISOString().slice(0, 10)
        )

    const [currentDateInfo] =
        useState(todays_date)

    const [idOfchangeDeliveryStatus, setIdOfchangeDeliveryStatus] =
        useState(0)

    const [cloneSearchTerm, setCloneSearchTerm] =
        useState("")


    // =========================================
    // LOGIN REDUCER
    // =========================================

    const userLoginReducer =
        useSelector(
            state => state.userLoginReducer
        )

    const { userInfo } =
        userLoginReducer


    // =========================================
    // GET ALL ORDERS REDUCER
    // =========================================

    const getAllOrdersReducer =
        useSelector(
            state => state.getAllOrdersReducer
        )

    const {
        orders = [],
        loading: loadingOrders
    } = getAllOrdersReducer


    // =========================================
    // CHANGE DELIVERY STATUS REDUCER
    // =========================================

    const changeDeliveryStatusReducer =
        useSelector(
            state => state.changeDeliveryStatusReducer
        )

    const {
        success: deliveryStatusChangeSuccess,
        loading: deliveryStatusChangeSpinner
    } = changeDeliveryStatusReducer


    // =========================================
    // TOKEN VALIDATION REDUCER
    // =========================================

    const checkTokenValidationReducer =
        useSelector(
            state => state.checkTokenValidationReducer
        )

    const {
        error: tokenError
    } = checkTokenValidationReducer


    // =========================================
    // GET ORDERS
    // =========================================

    useEffect(() => {

        if (!userInfo) {

            history.push("/login")

        } else {

            dispatch(
                checkTokenValidation()
            )

            dispatch(
                getAllOrders()
            )

        }

    }, [userInfo, dispatch, history])


    // =========================================
    // SESSION EXPIRED
    // =========================================

    useEffect(() => {

        if (
            userInfo &&
            tokenError === "Request failed with status code 401"
        ) {

            alert(
                "Session expired, please login again."
            )

            dispatch(
                logout()
            )

            history.push("/login")

            window.location.reload()

        }

    }, [
        userInfo,
        tokenError,
        dispatch,
        history
    ])


    // =========================================
    // CHANGE DELIVERY STATUS
    // =========================================

    const changeDeliveryStatusHandler =
        (id, status) => {

            setIdOfchangeDeliveryStatus(id)

            const productData = {

                is_delivered: status,

                delivered_at:
                    status
                        ? currentDateInfo
                        : "Not Delivered"

            }

            dispatch(
                changeDeliveryStatus(
                    id,
                    productData
                )
            )

        }


    // =========================================
    // DELIVERY STATUS SUCCESS
    // =========================================

    useEffect(() => {

        if (deliveryStatusChangeSuccess) {

            alert(
                "Delivery status changed successfully"
            )

            dispatch({
                type: CHANGE_DELIVERY_STATUS_RESET
            })

            dispatch(
                getAllOrders()
            )

        }

    }, [
        deliveryStatusChangeSuccess,
        dispatch
    ])


    // =========================================
    // SEARCH
    // =========================================

    const handleSearchTerm = (term) => {

        setCloneSearchTerm(
            term.toLowerCase()
        )

    }


    // =========================================
    // FILTER ORDERS
    // =========================================

    const filteredOrders =
        orders.filter((item) => {

            return (

                item.name
                    .toLowerCase()
                    .includes(cloneSearchTerm)

                ||

                item.ordered_item
                    .toLowerCase()
                    .includes(cloneSearchTerm)

                ||

                item.address
                    .toLowerCase()
                    .includes(cloneSearchTerm)

            )

        })


    // =========================================
    // UI
    // =========================================

    return (

        <div>

            {/* LOADING */}

            {loadingOrders && (

                <span
                    style={{
                        display: "flex",
                        alignItems: "center"
                    }}
                >

                    <h5>
                        Getting Orders
                    </h5>

                    <span className="ml-2">

                        <Spinner
                            animation="border"
                        />

                    </span>

                </span>

            )}


            {/* SEARCH */}

            {userInfo &&
                userInfo.admin && (

                    <SearchBarForOrdersPage
                        handleSearchTerm={
                            handleSearchTerm
                        }
                        placeholderValue={
                            placeholderValue
                        }
                    />

                )
            }


            {/* ORDERS */}

            {filteredOrders.length > 0 ? (

                <Table
                    className="mt-2"
                    striped
                    bordered
                    responsive
                >

                    <thead>

                        <tr
                            className="p-3 bg-info text-white text-center"
                        >

                            <th>
                                Order Id
                            </th>

                            <th>
                                Customer Name
                            </th>

                            <th>
                                Card Used
                            </th>

                            <th>
                                Delivery Address
                            </th>

                            <th>
                                Ordered Item
                            </th>

                            <th>
                                Paid Status
                            </th>

                            <th>
                                Paid On
                            </th>

                            <th>
                                Total Amount
                            </th>

                            <th>
                                Delivered Status
                            </th>

                            <th>
                                Delivered On
                            </th>

                            {userInfo &&
                                userInfo.admin && (

                                    <th>
                                        Delivery Status
                                    </th>

                                )
                            }

                        </tr>

                    </thead>


                    <tbody>

                        {filteredOrders.map(
                            (order, idx) => (

                                <tr
                                    key={idx}
                                    className="text-center"
                                >

                                    {/* ORDER ID */}

                                    <td>
                                        {order.id}
                                    </td>


                                    {/* CUSTOMER */}

                                    <td>
                                        {order.name}
                                    </td>


                                    {/* CARD */}

                                    <td>
                                        {order.card_number}
                                    </td>


                                    {/* ADDRESS */}

                                    <td>
                                        {order.address}
                                    </td>


                                    {/* ITEM */}

                                    <td>
                                        {order.ordered_item}
                                    </td>


                                    {/* PAID STATUS */}

                                    <td>

                                        {order.paid_status ? (

                                            <i
                                                className="fas fa-check-circle text-success"
                                            ></i>

                                        ) : (

                                            <i
                                                className="fas fa-times-circle text-danger"
                                            ></i>

                                        )}

                                    </td>


                                    {/* PAID DATE */}

                                    <td>
                                        {dateCheck(
                                            order.paid_at
                                        )}
                                    </td>


                                    {/* TOTAL */}

                                    <td>
                                        {order.total_price} INR
                                    </td>


                                    {/* DELIVERED */}

                                    <td>

                                        {order.is_delivered ? (

                                            <i
                                                className="fas fa-check-circle text-success"
                                            ></i>

                                        ) : (

                                            <i
                                                className="fas fa-times-circle text-danger"
                                            ></i>

                                        )}

                                    </td>


                                    {/* DELIVERED DATE */}

                                    <td>
                                        {order.delivered_at}
                                    </td>


                                    {/* DELIVERY BUTTON */}

                                    {userInfo &&
                                        userInfo.admin && (

                                            <td>

                                                {order.is_delivered ? (

                                                    <button
                                                        className="btn btn-outline-danger btn-sm"
                                                        onClick={() =>
                                                            changeDeliveryStatusHandler(
                                                                order.id,
                                                                false
                                                            )
                                                        }
                                                    >

                                                        {deliveryStatusChangeSpinner &&
                                                        idOfchangeDeliveryStatus ===
                                                            order.id ? (

                                                            <Spinner
                                                                animation="border"
                                                                size="sm"
                                                            />

                                                        ) : (

                                                            "Mark as Undelivered"

                                                        )}

                                                    </button>

                                                ) : (

                                                    <button
                                                        className="btn btn-outline-primary btn-sm"
                                                        onClick={() =>
                                                            changeDeliveryStatusHandler(
                                                                order.id,
                                                                true
                                                            )
                                                        }
                                                    >

                                                        {deliveryStatusChangeSpinner &&
                                                        idOfchangeDeliveryStatus ===
                                                            order.id ? (

                                                            <Spinner
                                                                animation="border"
                                                                size="sm"
                                                            />

                                                        ) : (

                                                            "Mark as delivered"

                                                        )}

                                                    </button>

                                                )}

                                            </td>

                                        )
                                    }

                                </tr>

                            )
                        )}

                    </tbody>

                </Table>

            ) : (

                <Message variant="info">
                    No orders yet.
                </Message>

            )}

        </div>

    )

}


export default OrdersListPage
